RESIDENT_NAMES.cartographer='柏岚';
for(const [trait,t] of Object.entries(TRAITS))ITEMS['seed_rye_'+trait]={...ITEMS.seedRye,trait,name:t.name+'黑麦种子',desc:t.desc+' 可稳定留种。'};
const copy=x=>JSON.parse(JSON.stringify(x)),distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
